export class ColumnHeaderClickEvent extends Event{static eventName="columnheaderclick";data;constructor(e,t){super(ColumnHeaderClickEvent.eventName),this.data={column:e,columnIndex:t}}}export class ContextMenuColumnSortClickEvent extends Event{static eventName="contextmenucolumnsortclick";data;constructor(e){super(ContextMenuColumnSortClickEvent.eventName),this.data={column:e}}}export class ContextMenuHeaderResetClickEvent extends Event{static eventName="contextmenuheaderresetclick";constructor(){super(ContextMenuHeaderResetClickEvent.eventName)}}export class NewUserFilterTextEvent extends Event{static eventName="newuserfiltertext";data;constructor(e){super(NewUserFilterTextEvent.eventName,{composed:!0}),this.data={filterText:e}}}export class BodyCellFocusedEvent extends Event{static eventName="cellfocused";data;constructor(e,t){super(BodyCellFocusedEvent.eventName,{composed:!0}),this.data={cell:e,row:t}}}